mapper.select:
SELECT COUNT(1)
FROM counter_event_inbox
WHERE event_id = #{eventId}
  AND entity_type = #{entityType}
  AND entity_id = #{entityId}
  AND metric = #{metric}
  AND delta = #{delta}
  AND user_id = #{userId}
  AND fact_epoch = #{factEpoch}

SELECT entity_type, entity_id
FROM counter_snapshot
WHERE metric IN ('like', 'fav')

  AND (
        BINARY entity_type > BINARY #{afterEntityType}
        OR (
            BINARY entity_type = BINARY #{afterEntityType}
            AND BINARY entity_id > BINARY #{afterEntityId}
        )
      )

  AND (
        BINARY entity_type < BINARY #{throughEntityType}
        OR (
            BINARY entity_type = BINARY #{throughEntityType}
            AND BINARY entity_id <= BINARY #{throughEntityId}
        )
      )
GROUP BY entity_type, entity_id
ORDER BY BINARY entity_type, BINARY entity_id
LIMIT #{limit}
